mapper.update:
UPDATE EDU_TRAIN_MAKER
   SET APPLY_FLAG = #{flag, jdbcType=NUMERIC},
       UPDATE_DATE = SYSDATE,
       UPDATED_BY = #{adminID, jdbcType=VARCHAR},
       UPDATED_IP = #{adminIP, jdbcType=VARCHAR}
 WHERE APPLY_NO = #{applyNo, jdbcType=NUMERIC}
   AND ACTIVITY = 1
   AND EXISTS (SELECT 1 FROM EDU_TRAIN_MAKER X
                WHERE X.APPLY_NO = #{applyNo, jdbcType=NUMERIC}
                  AND X.ACTIVITY = 1
                  AND X.MAKER_PERSON_ID = #{makerPersonId, jdbcType=VARCHAR}
                  AND NVL(TO_CHAR(X.CONFIRM_FLAG), '1') = '1')

