mapper.select:
SELECT , (SELECT COUNT(1) FROM EDU_STUDENT_APPLY X WHERE X.BASIC_NO = A.BASIC_NO AND X.ACTIVITY = 1 AND X.CPNY_ID = A.CPNY_ID) AS APPLY_COUNT, NVL(REGEXP_COUNT(B.PLAN_EMPLOYEE_EMPID, '[^,]+'), 0) AS PLANNED_COUNT
AND M.MAKER_LEVEL > 0 AND B.ACTIVITY = '1' AND B.CPNY_ID = #{cpnyId, jdbcType=VARCHAR} AND EXISTS (SELECT 1 FROM EDU_PLAN_MANAGER P WHERE P.PLAN_NO = B.PLAN_NO AND P.ISNOT_APPLY = 'Y')
AND A.STU_PERSON_ID = #{stuPersonId, jdbcType=VARCHAR}
AND DBMS_LOB.INSTR(',' || REPLACE(B.PLAN_EMPLOYEE_EMPID, ' ', '') || ',', ',' || H.EMPID || ',') > 0
AND TO_CHAR(M.APPLY_FLAG) = #{flag, jdbcType=VARCHAR}
ORDER BY CASE TO_CHAR(M.APPLY_FLAG) WHEN '1' THEN 1 WHEN '2' THEN 2 ELSE 3 END, A.STU_LOCAL_NAME, M.CONFIRM_FLAG DESC, B.COURSE_NAME_CODE
